#[inline]
pub(super) fn sample(table: &[i16; 1025], phase: f32) -> f32 {
    let scaled = phase * 1024.0;
    let index = scaled as usize;
    let fraction = scaled - index as f32;
    let index = index & 1023;
    let first = table[index] as f32;
    (first + (table[index + 1] as f32 - first) * fraction) * (1.0 / 32767.0)
}

